/* @lc app=leetcode id=3077 lang=kotlin */ class Solution { fun maximumStrength(nums: IntArray, k: Int): Long = (1..k).fold(LongArray(nums.size + 1)) { gp, j -> ((k - j + 1) * (if (j % 2 == 1) 1 else -1)).toLong().let { w -> (1..nums.size).runningFold(Long.MIN_VALUE / 4 to Long.MIN_VALUE / 4) { (f, g), i -> (maxOf(f, gp[i - 1]) + w * nums[i - 1]).let { nf -> nf to maxOf(g, nf) } }.map { it.second }.toLongArray() } }.last() }